// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(this)); }
    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        vm.assume(amount < 1 ether);
        vm.assume(amount >= 0);
        uint256 balanceBefore = c.balances(sender);
        vm.deal(sender, amount);
        vm.prank(sender);
        c.Deposit{value: amount}();
        uint256 balanceAfter = c.balances(sender);
        assertTrue(balanceAfter == balanceBefore);
    }
}
